extension StreamError {
    /// Reads `{error: {type, code, message, ...}, request_id}` or `{error: "code", message}`.
    static func parse(_ data: Data, requestID: String?) -> StreamError {
        let root = (try? JSONDecoder().decode(TungoCoding.Lenient.self, from: data))?.value
