                type: object["type"]?.stringValue, code: object["code"]?.stringValue,
                serverMessage: object["message"]?.stringValue, requestID: id, extra: extra)
        }
        return StreamError(
            type: nil, code: root?["error"]?.stringValue ?? root?["code"]?.stringValue,
            serverMessage: root?["message"]?.stringValue, requestID: id)
    }
